// DOM layout and element style: key elements located by role and name or by visible text, compared with
// the reference's boxes and computed styles (layout.json, generated by tools/export-frames.mjs). See
// ../README.md "Metric".
import { locate } from './capture.mjs';

/**
 * In-page: box and computed style of `node`. Colours are resolved to sRGB through a canvas (Chromium
 * reports Tailwind's oklch() colours verbatim). `background` is the first opaque-ish background of the
 * element or its ancestors (what the text actually sits on).
 */
function readElement(node) {
  const canvas = document.createElement('canvas');
  canvas.width = 1;
  canvas.height = 1;
  const context = canvas.getContext('2d', { willReadFrequently: true });
  const rgba = (value) => {
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = '#000';
    context.fillStyle = value;
    context.fillRect(0, 0, 1, 1);
    const [r, g, b, a] = context.getImageData(0, 0, 1, 1).data;
    return [r, g, b, a];
  };
  const rect = node.getBoundingClientRect();
  const style = getComputedStyle(node);
  let background = [255, 255, 255];
  for (let element = node; element; element = element.parentElement) {
    const colour = rgba(getComputedStyle(element).backgroundColor);
    if (colour[3] >= 128) {
      background = colour.slice(0, 3);
      break;
    }
  }
  const px = (value) => Math.round(Number.parseFloat(value) || 0);
  const fontSize = Number.parseFloat(style.fontSize);
  const borderWidth = px(style.borderTopWidth) + px(style.borderRightWidth) + px(style.borderBottomWidth) + px(style.borderLeftWidth);
  return {
    x: Math.round(rect.x + window.scrollX),
    y: Math.round(rect.y + window.scrollY),
    width: Math.round(rect.width),
    height: Math.round(rect.height),
    fontSize,
    fontWeight: Number(style.fontWeight),
    lineHeight: style.lineHeight === 'normal' ? Math.round(fontSize * 1.2) : px(style.lineHeight),
    color: rgba(style.color).slice(0, 3),
    background,
    radius: px(style.borderTopLeftRadius),
    padding: [px(style.paddingTop), px(style.paddingRight), px(style.paddingBottom), px(style.paddingLeft)],
    border: borderWidth ? rgba(style.borderTopColor).slice(0, 3) : null
  };
}

/** Page-coordinate boxes and styles of the frame's key elements (see `readElement`); null for elements not found. */
export async function measure(page, specs) {
  const boxes = {};
  for (const spec of specs) {
    const element = locate(page, spec);
    boxes[spec.id] = (await element.count()) ? await element.evaluate(readElement).catch(() => null) : null;
  }
  return boxes;
}

/** 1 within `full`, linearly down to 0 at `zero`. */
const ramp = (error, full, zero) => Math.min(1, Math.max(0, 1 - (error - full) / (zero - full)));

function lab([r, g, b]) {
  const linear = (value) => {
    const c = value / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  };
  const [lr, lg, lb] = [linear(r), linear(g), linear(b)];
  const f = (t) => (t > 0.008856 ? Math.cbrt(t) : 7.787 * t + 16 / 116);
  const x = f((lr * 0.4124 + lg * 0.3576 + lb * 0.1805) / 0.95047);
  const y = f(lr * 0.2126 + lg * 0.7152 + lb * 0.0722);
  const z = f((lr * 0.0193 + lg * 0.1192 + lb * 0.9505) / 1.08883);
  return [116 * y - 16, 500 * (x - y), 200 * (y - z)];
}
const deltaE = (a, b) => Math.hypot(...lab(a).map((value, index) => value - lab(b)[index]));

// Tolerances (design-review precision): see ../README.md "Metric".
export const LAYOUT = {
  position: [4, 24], // px of the worse of |dx|, |dy| at the top-left corner: full credit, no credit
  size: [0.04, 0.15], // relative width or height error (at least 2 px counts as full)
  fontSize: [0, 2], // px
  fontWeight: [0, 300],
  lineHeight: [1, 6], // px
  colour: [3, 15], // ΔE76 (text colour, background, border colour)
  radius: [1, 6], // px
  padding: [2, 12] // px, summed over the four sides
};

/**
 * Style credit: the product of the font size, weight, line height, text colour, background, radius,
 * padding and border colour credits (an element is right only when every property is).
 */
function styleCredit(want, got) {
  const parts = [
    ramp(Math.abs(got.fontSize - want.fontSize), ...LAYOUT.fontSize),
    ramp(Math.abs(got.fontWeight - want.fontWeight), ...LAYOUT.fontWeight),
    ramp(Math.abs(got.lineHeight - want.lineHeight), ...LAYOUT.lineHeight),
    ramp(deltaE(got.color, want.color), ...LAYOUT.colour),
    ramp(deltaE(got.background, want.background), ...LAYOUT.colour),
    ramp(Math.abs(got.radius - want.radius), ...LAYOUT.radius),
    ramp(got.padding.reduce((sum, value, index) => sum + Math.abs(value - want.padding[index]), 0), ...LAYOUT.padding),
    want.border || got.border ? (want.border && got.border ? ramp(deltaE(got.border, want.border), ...LAYOUT.colour) : 0) : 1
  ];
  return parts.reduce((product, value) => product * value, 1);
}

// Reading order: boxes that overlap vertically by at least half the shorter one share a row (left to right).
const before = (a, b) => (Math.min(a.y + a.height, b.y + b.height) - Math.max(a.y, b.y) >= Math.min(a.height, b.height) / 2 ? a.x - b.x : a.y - b.y);

/**
 * Scores measured elements against the reference's (both `{ id: element | null }`): per element, 0 when
 * missing, else the mean of position credit (top-left corner) and size credit (the worse of width and
 * height), times the style credit (`styleCredit`); the frame score is 0.8 x the element mean + 0.2 x the order
 * score (share of neighbouring pairs, in reference reading order, that keep their order) x the share of
 * elements found.
 */
export function scoreLayout(reference, measured) {
  const ids = Object.keys(reference).filter((id) => reference[id]);
  const elements = {};
  const sizeCredit = (got, want) => ramp(Math.max(0, Math.abs(got - want) - 2) / Math.max(1, want), ...LAYOUT.size);
  for (const id of ids) {
    const want = reference[id];
    const got = measured[id];
    if (!got) {
      elements[id] = 0;
      continue;
    }
    const position = ramp(Math.max(Math.abs(got.x - want.x), Math.abs(got.y - want.y)), ...LAYOUT.position);
    const size = Math.min(sizeCredit(got.width, want.width), sizeCredit(got.height, want.height));
    elements[id] = ((position + size) / 2) * styleCredit(want, got);
  }
  const found = ids.filter((id) => measured[id]);
  const inOrder = [...found].sort((a, b) => before(reference[a], reference[b]));
  let kept = 0;
  for (let index = 1; index < inOrder.length; index += 1) if (before(measured[inOrder[index - 1]], measured[inOrder[index]]) <= 0) kept += 1;
  const order = inOrder.length > 1 ? kept / (inOrder.length - 1) : found.length ? 1 : 0;
  const mean = ids.length ? ids.reduce((sum, id) => sum + elements[id], 0) / ids.length : 0;
  const coverage = ids.length ? found.length / ids.length : 0;
  return { score: 0.8 * mean + 0.2 * order * coverage, coverage, order, elements };
}
